import math

def is_simple_power(x, n):
    """
    Returns true if a number x is a simple power of n and false in other cases.
    x is a simple power of n if n**int=x
    """
    if n == 0:
        return x == 0
    if n == 1:
        return x == 1
    if x < 0:
        return False
    if math.log(x, n) % 1 == 0:
        return True
    return False

