def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    def shift_vowel(vowel):
        if vowel == 'a':
            return 'c'
        elif vowel == 'e':
            return 'g'
        elif vowel == 'i':
            return 'k'
        elif vowel == 'o':
            return 'q'
        elif vowel == 'u':
            return 'y'
        elif vowel == 'A':
            return 'C'
        elif vowel == 'E':
            return 'G'
        elif vowel == 'I':
            return 'K'
        elif vowel == 'O':
            return 'Q'
        elif vowel == 'U':
            return 'Y'
        else:
            return vowel

    encoded = []
    for char in message:
        if char.isalpha():
            swapped = char.swapcase()
            if swapped in ['A', 'E', 'I', 'O', 'U', 'a', 'e', 'i', 'o', 'u']:
                encoded.append(shift_vowel(char))
            else:
                encoded.append(swapped)
        else:
            encoded.append(char)
    return ''.join(encoded)

