            return b
        else:
            return a if isinstance(a, (int, float)) else b
    elif b_parsed > a_parsed:
        if isinstance(b, str):
            return b
        elif isinstance(a, str):
            return a
        else:
            return b if isinstance(b, (int, float)) else a
    else:
        if isinstance(a, str) and isinstance(b, str):
            return None
        elif isinstance(a, str) or isinstance(b, str):
            return None
        else:
            return None

